package com.financecoach.dto;
import com.financecoach.entity.BillingFrequency;import java.math.BigDecimal;import java.time.LocalDate;
public class SubscriptionDto {private Long id;private String name;private BigDecimal amount;private BillingFrequency billingFrequency;private LocalDate nextPaymentDate;private String category;private boolean active;public SubscriptionDto(){}public SubscriptionDto(Long id,String name,BigDecimal amount,BillingFrequency billingFrequency,LocalDate nextPaymentDate,String category,boolean active){this.id=id;this.name=name;this.amount=amount;this.billingFrequency=billingFrequency;this.nextPaymentDate=nextPaymentDate;this.category=category;this.active=active;}public Long getId(){return id;}public void setId(Long v){id=v;}public String getName(){return name;}public void setName(String v){name=v;}public BigDecimal getAmount(){return amount;}public void setAmount(BigDecimal v){amount=v;}public BillingFrequency getBillingFrequency(){return billingFrequency;}public void setBillingFrequency(BillingFrequency v){billingFrequency=v;}public LocalDate getNextPaymentDate(){return nextPaymentDate;}public void setNextPaymentDate(LocalDate v){nextPaymentDate=v;}public String getCategory(){return category;}public void setCategory(String v){category=v;}public boolean isActive(){return active;}public void setActive(boolean v){active=v;}}
